sys_script_include.script:
/**
 * @typedef MarkdownMapping
 * @property {string} display_name
 * @property {string} sys_id
 * @property {string} [folder]
 * @property {string} file_link
 */
/**
 * @typedef CatItemMarkdownMappingExt
 */
/** @typedef {CatItemMarkdownMappingExt & MarkdownMapping} CatItemMarkdownMapping */
/**
 * @typedef FlowMarkdownMappingExt
 * @property {string} internal_name
 */
/** @typedef {FlowMarkdownMappingExt & MarkdownMapping} FlowMarkdownMapping */
/**
 * @typedef TableMarkdownMappingExt
 * @property {string} name
 */
/** @typedef {TableMarkdownMappingExt & MarkdownMapping} TableMarkdownMapping */
/**
 * @typedef VarSetMarkdownMappingExt
 * @property {string} internal_name
 */
/** @typedef {VarSetMarkdownMappingExt & MarkdownMapping} VarSetMarkdownMapping */

var ReferenceLinkMapper = (function() {
    var instanceUri = gs.getProperty('glide.servlet.uri');

    ReferenceLinkMapperConstructor = Class.create();

    function getInstanceUri(glideRecord) {
        return instanceUri + 'nav_to.do?uri=' + encodeURIComponent(gr.getLink(true));
    }
    /**
     * @template {MarkdownMapping} T
     * @param {string} sys_id
     * @param {T[]} mappings
     * @returns {(T | undefined)}
     */
    function getMappingBySysId(sys_id, mappings) {
        for (var i = 0; i < mappings.length; i++) {
            var item = mappings[i];
            if (item == sys_id)
                return item;
        }
    }

    ReferenceLinkMapperConstructor.prototype = {
        _action_md_mappings: [],
        _cat_item_md_mappings: [],
        _flow_md_mappings: [],
        _table_md_mappings: [],
        _var_set_md_mappings: [],

        initialize: function() {
            var value = gs.getProperty('x_1645769_lte_dhlp.action_md_mappings');
            this._action_md_mappings = value ? JSON.parse(value) : [];
            value = gs.getProperty('x_1645769_lte_dhlp.cat_item_md_mappings');
            this._cat_item_md_mappings = value ? JSON.parse(value) : [];
            value = gs.getProperty('x_1645769_lte_dhlp.flow_md_mappings');
            this._flow_md_mappings = value ? JSON.parse(value) : [];
            value = gs.getProperty('x_1645769_lte_dhlp.table_md_mappings');
            this._table_md_mappings = value ? JSON.parse(value) : [];
            value = gs.getProperty('x_1645769_lte_dhlp.var_set_md_mappings');
            this._var_set_md_mappings = value ? JSON.parse(value) : [];
        },

        getActionMapping(action) {
            if (gs.nil(action))
                return;

            /** @type {FlowMarkdownMapping} */
            var item;
            if (action instanceof GlideRecord) {
                item = getMappingBySysId(this._action_md_mappings, action.getUniqueValue());
                if (!item) {
                    item = {
                        display_name: action.getValue('name'),
                        internal_name: action.getValue('internal_name'),
                        sys_id: action.getValue('sys_id'),
                        file_link: getInstanceUri(action)
                    };
                    this._action_md_mapping.push(item);
                }
                return item;
            }
            var n = '' + action;
            item = getMappingBySysId(this._action_md_mappings, action);
            if (item)
                return item;
            for (var i = 0; i < this._action_md_mappings.length; i++) {
                item = this._action_md_mappings[i];
                if (item.internal_name == action)
                    return item;
            }
            var gr = new GlideRecordSecure('sys_hub_action_type_definition');
            if (!gr.get(n)) {
                gr = new GlideRecordSecure('sys_hub_action_type_definition');
                gr.addQuery('internal_name', n);
                gr.query();
                if (!gr.next())
                    return;
            }
            item = {
                display_name: gr.getValue('name'),
                internal_name: gr.getValue('internal_name'),
                sys_id: gr.getValue('sys_id'),
                file_link: getInstanceUri(gr)
            };
            this._action_md_mappings.push(item);
            return item;
        },

        getCatItemMapping(cat_item) {
            if (gs.nil(cat_item))
                return;

            /** @type {MarkdownMapping} */
            var item;
            if (cat_item instanceof GlideRecord) {
                item = getMappingBySysId(this._cat_item_md_mappings, cat_item.getUniqueValue());
                if (!item) {
                    item = {
                        display_name: cat_item.getValue('name'),
                        sys_id: cat_item.getValue('sys_id'),
                        file_link: getInstanceUri(cat_item)
                    };
                    this._cat_item_md_mappings.push(item);
                }
                return item;
            }
            var n = '' + cat_item;
            item = getMappingBySysId(this._cat_item_md_mappings, n);
            if (item)
                return item;
            var gr = new GlideRecordSecure('sc_cat_item');
            if (!gr.get(n))
                return;
            item = {
                display_name: gr.getValue('name'),
                sys_id: gr.getValue('sys_id'),
                file_link: getInstanceUri(gr)
            };
            this._cat_item_md_mappings.push(item);
            return item;
        },

        getFlowMapping(flow) {
            if (gs.nil(flow))
                return;

            /** @type {FlowMarkdownMapping} */
            var item;
            if (flow instanceof GlideRecord) {
                item = getMappingBySysId(this._flow_md_mappings, flow.getUniqueValue());
                if (!item) {
                    item = {
                        display_name: flow.getValue('name'),
                        internal_name: flow.getValue('internal_name'),
                        sys_id: flow.getValue('sys_id'),
                        file_link: getInstanceUri(flow)
                    };
                    this._flow_md_mappings.push(item);
                }
                return item;
            }
            var n = '' + flow;
            item = getMappingBySysId(this._flow_md_mappings, n);
            if (item)
                return item;
            for (var i = 0; i < this._flow_md_mappings.length; i++) {
                item = this._flow_md_mappings[i];
                if (item.internal_name == n)
                    return item;
            }
            var gr = new GlideRecordSecure('sys_hub_flow');
            if (!gr.get(n)) {
                gr = new GlideRecordSecure('sys_hub_flow');
                gr.addQuery('internal_name', n);
                gr.query();
                if (!gr.next())
                    return;
            }
            item = {
                display_name: gr.getValue('name'),
                internal_name: gr.getValue('internal_name'),
                sys_id: gr.getValue('sys_id'),
                file_link: getInstanceUri(gr)
            };
            this._flow_md_mappings.push(item);
            return item;
        },

        getTableMapping(table) {
            if (gs.nil(table))
                return;

            /** @type {TableMarkdownMapping} */
            var item;
            if (table instanceof GlideRecord) {
                item = getMappingBySysId(this._table_md_mappings, table.getUniqueValue());
                if (!item) {
                    item = {
                        display_name: table.getValue('label'),
                        name: table.getValue('name'),
                        sys_id: table.getValue('sys_id'),
                        file_link: getInstanceUri(table)
                    };
                    this._table_md_mappings.push(item);
                }
                return item;
            }
            var n = '' + table;
            item = getMappingBySysId(this._table_md_mappings, n);
            if (item)
                return item;
            for (var i = 0; i < this._table_md_mappings.length; i++) {
                item = this._table_md_mappings[i];
                if (item.name == n)
                    return item;
            }
            var gr = new GlideRecordSecure('sys_db_object');
            if (!gr.get(n)) {
                gr = new GlideRecordSecure('sys_db_object');
                gr.addQuery('name', n);
                gr.query();
                if (!gr.next())
                    return;
            }
            item = {
                display_name: table.getValue('label'),
                name: table.getValue('name'),
                sys_id: gr.getValue('sys_id'),
                file_link: getInstanceUri(gr)
            };
            this._table_md_mappings.push(item);
            return item;
        },

        getVarSetMapping(variable_set) {
            if (gs.nil(variable_set))
                return;

            /** @type {VarSetMarkdownMapping} */
            var item;
            if (variable_set instanceof GlideRecord) {
                item = getMappingBySysId(this._var_set_md_mappings, variable_set.getUniqueValue());
                if (!item) {
                    item = {
                        display_name: variable_set.getValue('title'),
                        internal_name: variable_set.getValue('internal_name'),
                        sys_id: variable_set.getValue('sys_id'),
                        file_link: getInstanceUri(variable_set)
                    };
                    this._var_set_md_mappings.push(item);
                }
                return item;
            }
            var n = '' + variable_set;
            item = getMappingBySysId(this._var_set_md_mappings, n);
            if (item)
                return item;
            for (var i = 0; i < this._var_set_md_mappings.length; i++) {
                item = this._var_set_md_mappings[i];
                if (item.internal_name == n)
                    return item;
            }
            var gr = new GlideRecordSecure('item_option_new_set');
            if (!gr.get(n)) {
                gr = new GlideRecordSecure('item_option_new_set');
                gr.addQuery('internal_name', n);
                gr.query();
                if (!gr.next())
                    return;
            }
            item = {
                display_name: variable_set.getValue('title'),
                internal_name: variable_set.getValue('internal_name'),
                sys_id: gr.getValue('sys_id'),
                file_link: getInstanceUri(gr)
            };
            this._var_set_md_mappings.push(item);
            return item;
        },

        getActionUrl(action, current_folder) {
            /** @type {FlowMarkdownMapping} */
            var item = this.getActionMapping(action);
            if (item) {
                if (!item.folder || current_folder == item.folder)
                    return item.file_link;
                return (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link;
            }
        },

        getCatItemUrl(cat_item, current_folder) {
            /** @type {MarkdownMapping} */
            var item = this.getCatItemMapping(cat_item);
            if (item) {
                if (!item.folder || current_folder == item.folder)
                    return item.file_link;
                return (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link;
            }
        },

        getFlowUrl(flow, current_folder) {
            /** @type {FlowMarkdownMapping} */
            var item = this.getFlowMapping(flow);
            if (item) {
                if (!item.folder || current_folder == item.folder)
                    return item.file_link;
                return (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link;
            }
        },

        getTableUrl(flow, current_folder) {
            /** @type {TableMarkdownMapping} */
            var item = this.getTableMapping(flow);
            if (item) {
                if (!item.folder || current_folder == item.folder)
                    return item.file_link;
                return (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link;
            }
        },

        getVarSetUrl(flow, current_folder) {
            /** @type {VarSetMarkdownMapping} */
            var item = this.getVarSetMapping(flow);
            if (item) {
                if (!item.folder || current_folder == item.folder)
                    return item.file_link;
                return (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link;
            }
        },

        getActionMdLink(action, current_folder, isForTableCell) {
            if (!gs.nil(action)) {
                /** @type {FlowMarkdownMapping} */
                var item = this.getActionMapping(action);
                if (item) {
                    if (!item.folder || current_folder == item.folder)
                        return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(item.display_name, isForTableCell) + '](' + item.file_link + ')';
                    return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(item.display_name, isForTableCell) + '](' + (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link + ')';
                }
                var c = MarkdownGenerationContextConstructor.normalizeWhiteSpace(action);
                if (c)
                    return '`' + c + '`';
            }
            return '*Empty*';
        },

        getCatItemMdLink(cat_item, current_folder, isForTableCell) {
            if (!gs.nil(cat_item)) {
                /** @type {MarkdownMapping} */
                var item = this.getCatItemMapping(cat_item);
                if (item) {
                    if (!item.folder || current_folder == item.folder)
                        return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(item.display_name, isForTableCell) + '](' + item.file_link + ')';
                    return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(item.display_name, isForTableCell) + '](' + (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link + ')';
                }
                var c = MarkdownGenerationContextConstructor.normalizeWhiteSpace(cat_item);
                if (c)
                    return '`' + c + '`';
            }
            return '*Empty*';
        },

        getFlowMdLink(flow, current_folder, isForTableCell) {
            if (!gs.nil(flow)) {
                /** @type {FlowMarkdownMapping} */
                var item = this.getFlowMapping(flow);
                if (item) {
                    if (!item.folder || current_folder == item.folder)
                        return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(item.display_name, isForTableCell) + '](' + item.file_link + ')';
                    return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(item.display_name, isForTableCell) + '](' + (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link + ')';
                }
                var c = MarkdownGenerationContextConstructor.normalizeWhiteSpace(flow);
                if (c)
                    return '`' + c + '`';
            }
            return '*Empty*';
        },

        getTableMdLink(table, current_folder, isForTableCell) {
            if (!gs.nil(table)) {
                /** @type {TableMarkdownMapping} */
                var item = this.getTableMapping(table);
                if (item) {
                    if (!item.folder || current_folder == item.folder)
                        return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(item.display_name, isForTableCell) + '](' + item.file_link + ')';
                    return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(item.display_name, isForTableCell) + '](' + (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link + ')';
                }
                var c = MarkdownGenerationContextConstructor.normalizeWhiteSpace(table);
                if (c)
                    return '`' + c + '`';
            }
            return '*Empty*';
        },

        getColumnMdLink(table, field, current_folder, isForTableCell) {
            if (!gs.nil(field)) {
                /** @type {TableMarkdownMapping} */
                var item = this.getTableMapping(table);
                if (item) {
                    var gr = new GlideRecordSecure('sys_dictionary');
                    gr.addQuery('name', item.name);
                    var n = '' + field;
                    gr.addQuery('element', n);
                    gr.query();
                    if (gr.next()) {
                        l = gr.getValue('label');
                        n = gr.getValue('element');
                    } else {
                        l = n;
                    }
                    if (!item.folder)
                        return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(l, isForTableCell) + '](' + item.file_link + ')';
                    if (current_folder == item.folder)
                        return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(l, isForTableCell) + '](' + item.file_link + "#column-" + n + ')';
                    return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(l, isForTableCell) + '](' + (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link + "#column-" + n + ')';
                }
                var t = MarkdownGenerationContextConstructor.normalizeWhiteSpace(table);
                var e = MarkdownGenerationContextConstructor.normalizeWhiteSpace(field);
                if (t && e)
                    return '`[' + c + '.' + e + ']`';
            }
            return '*Empty*';
        },

        getVarSetMdLink(variable_set, current_folder, isForTableCell) {
            if (!gs.nil(variable_set)) {
                /** @type {VarSetMarkdownMapping} */
                var item = this.getVarSetMapping(variable_set);
                if (item) {
                    if (!item.folder || current_folder == item.folder)
                        return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(item.display_name, isForTableCell) + '](' + item.file_link + ')';
                    return '[' + MarkdownGenerationContextConstructor.escapeForMarkdown(item.display_name, isForTableCell) + '](' + (current_folder ? '../' + item.folder : item.folder) + '/' + item.file_link + ')';
                }
                var c = MarkdownGenerationContextConstructor.normalizeWhiteSpace(variable_set);
                if (c)
                    return '`[' + c + ']`';
            }
            return '*Empty*';
        },

        type: 'ReferenceLinkMapper'
    };

    return ReferenceLinkMapperConstructor;
})();
